sp_widget.client_script:
api.controller = function ($scope, $timeout) {
  $timeout(function () {

    var canvas = document.getElementById('gn-canvas');
    if (!canvas) return;
    var ctx = canvas.getContext('2d');

    var W, H, particles = [], mouse = { x: -9999, y: -9999 };

    /* Fresh indigo/blue/cyan palette — works on light background */
    var COLORS = [
      'rgba(99,102,241,',
      'rgba(59,130,246,',
      'rgba(6,182,212,',
      'rgba(139,92,246,',
      'rgba(79,70,229,'
    ];
    var COUNT = 90;

    function resize() {
      W = canvas.width  = canvas.offsetWidth;
      H = canvas.height = canvas.offsetHeight;
    }
    function rand(a, b) { return a + Math.random() * (b - a); }
    function choice(arr) { return arr[Math.floor(Math.random() * arr.length)]; }

    function Particle() { this.reset(); }
    Particle.prototype.reset = function () {
      this.x     = rand(0, W);
      this.y     = rand(0, H);
      this.vx    = rand(-0.25, 0.25);
      this.vy    = rand(-0.18, 0.18);
      this.r     = rand(1.5, 3.0);
      this.color = choice(COLORS);
      this.alpha = rand(0.25, 0.55);   /* lighter — suits white bg */
      this.life  = rand(0.3, 1);
      this.speed = rand(0.004, 0.010);
    };

    Particle.prototype.update = function () {
      this.life += this.speed;
      this.x    += this.vx;
      this.y    += this.vy;
      var dx   = this.x - mouse.x;
      var dy   = this.y - mouse.y;
      var dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < 100 && dist > 0) {
        var force = (100 - dist) / 100 * 0.5;
        this.x += (dx / dist) * force;
        this.y += (dy / dist) * force;
      }
      if (this.x < -10)    this.x = W + 10;
      if (this.x > W + 10) this.x = -10;
      if (this.y < -10)    this.y = H + 10;
      if (this.y > H + 10) this.y = -10;
    };

    function init() {
      particles = [];
      for (var i = 0; i < COUNT; i++) particles.push(new Particle());
    }

    function drawLine(a, b, dist) {
      var maxDist = 130;
      var opacity = (1 - dist / maxDist) * 0.12;   /* subtle on light bg */
      ctx.beginPath();
      ctx.strokeStyle = 'rgba(99,102,241,' + opacity + ')';
      ctx.lineWidth   = 0.7;
      ctx.moveTo(a.x, a.y);
      ctx.lineTo(b.x, b.y);
      ctx.stroke();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);

      for (var i = 0; i < particles.length; i++) {
        for (var j = i + 1; j < particles.length; j++) {
          var dx = particles[i].x - particles[j].x;
          var dy = particles[i].y - particles[j].y;
          var d  = Math.sqrt(dx * dx + dy * dy);
          if (d < 130) drawLine(particles[i], particles[j], d);
        }
      }

      for (var k = 0; k < particles.length; k++) {
        var p     = particles[k];
        p.update();
        var pulse = 0.55 + Math.sin(p.life * Math.PI * 2) * 0.35;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fillStyle   = p.color + (p.alpha * pulse).toFixed(3) + ')';
        ctx.globalAlpha = 1;
        ctx.fill();
      }

      requestAnimationFrame(draw);
    }

    document.addEventListener('mousemove', function (e) {
      var rect = canvas.getBoundingClientRect();
      mouse.x  = e.clientX - rect.left;
      mouse.y  = e.clientY - rect.top;
    });
    document.addEventListener('mouseleave', function () {
      mouse.x = -9999;
      mouse.y = -9999;
    });

    if (window.ResizeObserver) {
      new ResizeObserver(function () { resize(); init(); })
        .observe(canvas.parentElement);
    } else {
      window.addEventListener('resize', function () { resize(); init(); });
    }

    resize(); init(); draw();

  }, 100);
};

sp_widget.css:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

.gatenow-hero-wrapper {
  font-family: 'Inter', 'Segoe UI', sans-serif;
  margin-left: -15px;
  margin-right: -15px;
  width: calc(100% + 30px);
}

/* ── Hero ── */
.gn-hero {
  position: relative;
  width: 100%;
  min-height: 580px;
  background: linear-gradient(160deg, #f0f4ff 0%, #e8eeff 40%, #eef6ff 100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 100px 24px 80px;
}

/* ── Canvas ── */
#gn-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
}

/* ── Radial fade ── */
.gn-radial-fade {
  position: absolute;
  inset: 0;
  background: radial-gradient(
    ellipse 75% 65% at 50% 40%,
    transparent 0%,
    rgba(240,244,255,0.85) 100%
  );
  pointer-events: none;
  z-index: 2;
}

/* ── Content ── */
.gn-content {
  position: relative;
  z-index: 4;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  max-width: 720px;
}

/* ── Badge ── */
.gn-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  background: rgba(99,102,241,0.09);
  border: 1px solid rgba(99,102,241,0.22);
  color: rgba(79,70,229,0.90);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 5px 14px;
  border-radius: 100px;
  margin-bottom: 28px;
  animation: gnFadeUp 0.4s ease both;
}

.gn-badge-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #6366f1;
  box-shadow: 0 0 8px rgba(99,102,241,0.70);
  animation: gnPulse 2.2s ease-in-out infinite;
}

/* ── Heading ── */
.gn-heading {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: clamp(36px, 5.5vw, 68px);
  font-weight: 800;
  line-height: 1.08;
  letter-spacing: -0.03em;
  color: #1e1b4b;
  margin-bottom: 20px;
  animation: gnFadeUp 0.5s ease 0.05s both;
}

.gn-heading em {
  font-style: normal;
  background: linear-gradient(90deg, #6366f1 0%, #3b82f6 60%, #06b6d4 100%);
  background-size: 200% auto;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: gnShimmerText 6s linear infinite;
}

/* ── Sub ── */
.gn-sub {
  font-size: clamp(15px, 1.6vw, 18px);
  font-weight: 400;
  line-height: 1.72;
  color: rgba(30,27,75,0.52);
  max-width: 540px;
  margin-bottom: 40px;
  animation: gnFadeUp 0.5s ease 0.10s both;
}

/* ── Buttons ── */
.gn-btn-group {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
  animation: gnFadeUp 0.5s ease 0.16s both;
}

.gn-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 600;
  padding: 13px 26px;
  border-radius: 10px;
  text-decoration: none !important;
  cursor: pointer;
  transition: all 0.18s ease;
  white-space: nowrap;
  line-height: 1;
  border: none;
  font-family: 'Inter', sans-serif;
}

.gn-btn-primary {
  background: linear-gradient(135deg, #6366f1 0%, #3b82f6 100%);
  color: #fff;
  box-shadow: 0 4px 20px rgba(99,102,241,0.35),
              inset 0 1px 0 rgba(255,255,255,0.15);
}
.gn-btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 28px rgba(99,102,241,0.50);
  color: #fff;
}
.gn-btn-primary:hover .gn-btn-icon {
  transform: translateX(4px);
}

.gn-btn-secondary {
  background: rgba(99,102,241,0.07);
  border: 1px solid rgba(99,102,241,0.20) !important;
  color: rgba(79,70,229,0.80);
}
.gn-btn-secondary:hover {
  background: rgba(99,102,241,0.12);
  border-color: rgba(99,102,241,0.35) !important;
  color: #4f46e5;
  transform: translateY(-2px);
}

.gn-btn-icon {
  transition: transform 0.2s ease;
  flex-shrink: 0;
}

/* ── Keyframes ── */
@keyframes gnFadeUp {
  from { opacity: 0; transform: translateY(18px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes gnPulse {
  0%, 100% { transform: scale(1); opacity: 1; }
  50%       { transform: scale(1.7); opacity: 0.4; }
}

@keyframes gnShimmerText {
  from { background-position: 0% center; }
  to   { background-position: 200% center; }
}

/* ── Responsive ── */
@media (max-width: 640px) {
  .gn-hero    { padding: 80px 20px 60px; min-height: 480px; }
  .gn-heading { font-size: 34px; }
  .gn-sub     { font-size: 15px; }
}

sp_widget.script:
(function() {

  function optVal(opt, fallback) {
    return (opt && opt !== '') ? opt : fallback;
  }

  data.heading     = optVal(options.heading,     "Unlock Federal Funding for America's Future");
  data.description = optVal(options.description, "GateNow simplifies every step — discover open grants, confirm eligibility, and submit compliant federal applications all in one secure, guided platform.");
  data.badge       = "Federal Grant Management Platform";

  data.programs_page = optVal(options.programs_page, "grant_programs");
  data.apply_page    = optVal(options.apply_page,    "applicant_form");

})();
